export type RouteMap = {
  width: number;
  height: number;
  /** 沿路線量出的總長（公里） */
  km: number;
  major: string;
  mid: string;
  minor: string;
  rail: string;
  route: string;
  arrows: string;
  start: [number, number];
  /** 終點：和起點不同時才有 */
  finish?: [number, number];
  /** 每條路的順序號碼，和 chips 的 n 一致 */
  steps: { n: number; x: number; y: number }[];
  /** 有查到地點的加油打氣站 */
  stations: { x: number; y: number; text: string }[];
  /** 地標：side 是名字放在點的哪一邊 */
  landmarks: { x: number; y: number; text: string; side: "left" | "right" }[];
  labels: { x: number; y: number; text: string }[];
  /** 路線清單：照公告順序，換一條路加一號；station 是加油打氣站，mapped 表示圖上有畫 */
  chips: { n?: number; text: string; station?: boolean; mapped?: boolean }[];
};

